window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-pediatria-med-ped-03"]={"block":"med:med-pediatria-med-ped-03","label":"MED · MED PED 03","count":71,"questions":[{"id":"med-pediatria-med-ped-03-159090","number":"159090","sourceNumber":"159090","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Criança de 4 meses de idade vem à consulta médica trazida pela mãe, que está\nbastante preocupada, pois a filha não apresentou a\nreação esperada da BCG. O pediatra constata\nque não tem cicatriz da vacina na região deltoide do braço direito. A conduta mais indicada nesse\ncaso é:","options":{"A":"Revacinar imediatamente.","B":"Realizar PPD, se reator, iniciar tratamento.","C":"Aguardar até 6 meses de vida, se não fizer cicatriz, deverá ser revacinada.","D":"Nenhuma das alternativas acima está correta."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-108818","number":"108818","sourceNumber":"108818","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Assinale as afirmativas abaixo sobre IMUNIZAÇÃO e indique se são VERDADEIRAS\n\n(V) ou FALSAS(F). ( ) Devemos estabelecer intervalos de 30 dias entre a Vacina Tríplice viral e a\nVacina contra Varicela; e 15 dias entre a Vacina Tríplice viral e a Vacina da Febre amarela. ( ) A\nVacina BCG deve ser aplicada o mais precoce possível, preferencialmente após o nascimento, mas\nnão há necessidade de aplicar uma dose em crianças menores de cinco anos sem cicatriz vacinal. (\n\n) A aplicação de várias vacinas no mesmo dia oferece risco à criança ou ao adulto. ( ) A vacinação\ndeve ser suspensa em caso de Doença Febril\nAguda, com temperatura acima de 38,5 C e em\ncrianças em tratamento com imunossupressores. ( ) A Vacina Meningocócica C (CONJUGADA)\ndeve ser recomendada porque a Doneça Meningocócica apresenta alta letalidade, podendo ocorrer\nem qualquer faixa etária, porém é mais comum em crianças com idade superior a cinco anos.","options":{"A":"F - F - V - F - F","B":"V - F - F - V - F","C":"V - V - V - F - V","D":"V - F - F - F - V"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-29393","number":"29393","sourceNumber":"29393","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em relação às diferenças nas imunizações com microorganismo vivo atenuado e com\npartículas de microorganismos, assinale a afirmativa VERDADEIRA.","options":{"A":"Os dois tipos de vacinas tem frequência de efeitos colaterais semelhantes.","B":"As vacinas com vírus vivos atenuados levam a uma estimulação mais intensa do sistema\nimunológico.","C":"As vacinas com frações de microorganismo necessitam de replicação no organismo da pessoa\npara levar a um maior potencial imunogênico.","D":"As vacinas de vírus vivos atenuados geralmente necessitam de uma maior número de doses\nque as partículas de vírus para alcançar o\nmesmo potencial imunogênico.","E":"Nenhum desses tipos de vacina pode levar a sintomas leves de doença."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-29398","number":"29398","sourceNumber":"29398","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em relação às ações de controle da Hepatite B, após a imunização com três doses da\nvacina, deve-se confirmar a presença de imunidade pela sorologia. Que marcador de hepatite B é\npositivo na ?viragem sorológica? pós-vacinal?","options":{"A":"HBsAg.","B":"Anti-HBc total.","C":"Anti-HBc IgG.","D":"Anti-HBs","E":"Anti-HBe"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-29342","number":"29342","sourceNumber":"29342","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"A vacina BCG tem o seu efeito protetor mais evidente em qual forma de tuberculose?","options":{"A":"Óssea","B":"Pulmonar","C":"Ganglionar","D":"Miliar","E":"Renal"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-208404","number":"208404","sourceNumber":"208404","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"É contraindicação absoluta à vacina de febre amarela:","options":{"A":"Infecção pelo HIV","B":"Alergia a ovo","C":"Idade menor que 6 meses","D":"Uso de corticosteroides"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-208337","number":"208337","sourceNumber":"208337","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Desde 1990, não há registro de Poliomielite no Brasil mas a doença ainda ocorre em\noutras regiões no planeta. Com a reintrodução do sarampo no país, a preocupação agora é\ntambém com a Poliomielite, redobrando os cuidados para manter uma boa cobertura vacinal. A\nvacinação contra este agravo deve ser:","options":{"A":"A única forma de evitar a doença é através da vacinação e de profilaxia pós-contato com\nantibióticos de amplo espectro","B":"As crianças entre um e cinco anos de idade devem tomar 3 doses da vacina injetável contra\nPoliomielite (VIP)","C":"Feita com vacina oral (VOP) e com a vacina injetável (VIP) sendo agravo de notificação semanal\nnegativa/positiva","D":"Durante as campanhas como a que ocorreu em agosto deste ano, todas as crianças menores de\ncinco anos devem receber a VIP"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-81969","number":"81969","sourceNumber":"81969","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Para amamentar sem risco um recém-nascido de uma mãe que teve isolado no leite\nmaterno o vírus da hepatite B é necessário:","options":{"A":"Imunização ativa ao lactente nas primeiras 24h de vida, associado à administração de\nimunoglobulinas específica da hepatite B.","B":"Imunização ativa nos 30 dias de vida sem associação de imunoglobulinas específicas da\nhepatite B.","C":"Imunização ativa nos 60 dias de vida sem associação de imunoglobulinas específicas da\nhepatite B.","D":"Imunização ativa nos 90 dias de vida com associação de imunoglobulinas específicas da\nhepatite B.","E":"Imunização ativa com 45 dias de vida com associação imunoglobulinas específicas da hepatite\nB."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-46728","number":"46728","sourceNumber":"46728","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Você é médico de família e comunidade e deve orientar as mães no grupo de\npuericultura sobre vacinas para seus bebês.\nEm relação à idade e à vacina indicada, correlacione a\nprimeira coluna com a segunda, de acordo com o preconizado pelo programa nacional de\nimunização e marque a alternativa com a sequência correta. VACINAS: (1) vacina BCG, (2) vacina\ncontra Rotavírus, (3) vacina contra Hepatite B, (4) vacina tríplice bacteriana (DTP) e\npoliomielite, (5)\nvacina contra H1N1, (6) vacina contra pneumococo 10. IDADE: ( ) aplicação intramuscular ao\nnascer, com 1 e 6 meses. ( ) aplicação intradérmica ao nascer. ( ) aplicação aos 2, 4, 6 e 15 meses.\n( ) aplicação a partir dos seis meses. ( ) aplicação oral aos 2 e 4 meses. ( ) aplicar\nintramuscular a\nintervalos de 60 dias com 2, 4, 6 e 15 meses.","options":{"A":"3-1-2-5-6-4","B":"3-1-4-5-2-6","C":"3-2-1-4-5-6","D":"4-2-5-1-3-6","E":"4-1-5-3-6-2"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-34291","number":"34291","sourceNumber":"34291","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"O Bebê de Manuela, Eric, deveria receber uma vacina aos 09 meses. Para orientar a\nmãe em relação à idade e à vacina\nindicada, correlacione a primeira coluna com a segunda, de\nacordo com a preconizado pelo Programa Nacional de Imunização: Primeira coluna: (1) vacina\nBCG; (2) vacina contra Rotavírus; (3) vacina contra Hepatite B; (4) vacina tríplice bacteriana (DTP)\ne contra Poliomielite; (5) vacina contra H1N1; (6) vacina contra Febre Amarela. Segunda coluna ( )\naplicação intramuscular ao nascer, com 01 e 06 meses; ( ) aplicação intradérmica ao nascer; ( )\naplicação subcutânea aos 09 meses; ( ) aplicação a partir dos seis meses; ( ) aplicação aos 02 e 04\nmeses; ( ) aplicar a intervalos de 60 dias com 2, 4, 6 e 15 meses.","options":{"A":"3 - 1 - 6 - 5 - 2 - 4","B":"3 - 2 - 1 - 4 - 5 - 6","C":"4 - 1 - 5 - 3 - 6 - 2","D":"4 - 2 - 5 - 1 - 3 - 6","E":"3 - 1 - 2 - 5 - 6 - 4"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-26534","number":"26534","sourceNumber":"26534","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Uma criança de 3 anos, nunca vacinada, comparece ao centro de saúde. A conduta\nideal, nessa situação, é administrar:","options":{"A":"BCG, pólio oral, hepatite B, DTP e tríplice viral (SCR).","B":"BCG e hepatite B e agendar as demais","C":"Pólio oral, DTP+Hb, hepatite B e tríplice viral (SCR)","D":"Pólio oral, DTP, hepatite B, sarampo e BCG se PPD negativo","E":"Apenas 1 das vacinas virais e agendar as demais"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-13259","number":"13259","sourceNumber":"13259","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Criança de 01 ano de idade chega ao Posto de Saúde para receber a vacina tríplice\nviral (S&C). Conforme calendário de vacinação\nrecomendado pelo Ministério da Saúde (Brasil),\nespera-se que tenha recebido anteriormente as seguintes vacinas:","options":{"A":"BCG- Hepatite B- Haemophilus tipo B- Pólio e rotavirus.","B":"DTP- BCG- Polio- Hepatite A- Hepatite B.","C":"BCG- Pólio- DTP- Haemophilus tipo B- Hepatite B - rotavirus e febre amarela.","D":"BCG- Hepatite A e B- Pólio- Haemophilus tipo B e febre amarela.","E":"Haemophilus tipo B- BCG- Hepatite A- Hepatite B e tríplice viral dose inicial."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-7430","number":"7430","sourceNumber":"7430","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Pré-escolar de três anos é atendido com história de febre alta há horas. Constata-se\ntoxemia, sialorreia, estridor e dispneia\nprogressiva. Além da internação hospitalar, está indicado\nrealização imediata de:","options":{"A":"drenagem torácica.","B":"radiografia de tórax.","C":"radiografia lateral de pescoço.","D":"permeabilização de vias aéreas.","E":"instalar equipo de soro para hidratação."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-7524","number":"7524","sourceNumber":"7524","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Derrame pleural com quadro evolutivo rápido, exame radiológico de pneumatoceles,\nderrame pleural e abscesso pulmonar, em\nlactente de 6 meses, com broncopneumonia e estado\ngeral comprometido; trata-se de infecção causada mais provavelmente por:","options":{"A":"staphylococcus aureus.","B":"estreptococo beta-hemolítico do grupo A.","C":"haemophilus influenzae do tipo B.","D":"mycoplasma pneumoniae.","E":"pseudomonas aeruginosa."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-284607","number":"284607","sourceNumber":"284607","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Menino, 7 anos de idade, é levado à Unidade de Pronto Atendimento por ter pisado em\num prego enferrujado quando se encontrava em\num abrigo de animais. O genitor não conseguiu\nretirar o prego, que permaneceu encravado. Sua carteira de vacinação mostra-se desatualizada\ndesde os 12 meses de idade. Considerando a situação descrita, Identifique a afirmação correta\nquanto aos cuidados desse paciente.","options":{"A":"O uso de água oxigenada não evidencia vantagens sobre a lavagem com soro fisiológico\ncomum.","B":"A lavagem com clorexedina não mostrou eficácia no combate à infecção local.","C":"O desbridamento pode ser evitado, se a retirada do prego ocorrer antes de duas horas do\nferimento ter ocorrido.","D":"O curativo oclusivo pós-desbridamento está contraindicado, devendo ser feito um curativo\npermeável."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-13343","number":"13343","sourceNumber":"13343","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Paciente, 12 dias de vida, é levado à primeira consulta, após um nascimento por parto\nnormal sem intercorrências. O seu exame físico é normal, pesa 3210 gramas.\n\nSegundo Ministério da Saúde, as vacinas que estão indicadas são:","options":{"A":"antirrotavírus e BCG","B":"anti-Haemophylus tipo B e BCG","C":"BCG e hepatite B","D":"anti-hepatite A e BCG","E":"antipneumococos 7-valente e hepatite B"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-250011","number":"250011","sourceNumber":"250011","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Vacina que não pode ser utilizada na gravidez:","options":{"A":"Hepatite C.","B":"Raiva.","C":"Dupla adulto.","D":"Gripe."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-111902","number":"111902","sourceNumber":"111902","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Segundo recomendação do Calendário Básico de Vacinação da Criança, elaborado\npelo Ministério da Saúde, o esquema básico\ncompleto da vacina contra a Hepatite B consiste em:","options":{"A":"duas doses: a primeira nas primeiras 12 horas de vida e a segunda após 30 dias da primeira.","B":"duas doses: a primeira nas primeiras 12 horas de vida e a segunda após 60 dias da primeira.","C":"três doses: a primeira nas primeiras 12 horas de vida, a segunda após 30 dias da primeira e a\nterceira após 180 dias da primeira.","D":"três doses: a primeira nas primeiras 12 horas de vida, a segunda após 30 dias da primeira e a\nterceira após 60 dias da primeira."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-199676","number":"199676","sourceNumber":"199676","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Lactente de seis meses de idade é levado ao ambulatório para consulta de rotina. O\nexame físico revela ausência de cicatriz vacinal para BCG, sem outras alterações. No cartão da\ncriança, consta registro de vacinação contra tuberculose no período neonatal, realizada na\nmaternidade. Qual a melhor conduta nesse caso?","options":{"A":"Considerar o lactente imunizado e não revacinar.","B":"Revacinar o lactente, sem fazer o teste tuberculínico.","C":"Fazer o teste tuberculínico e, se for negativo, revacinar o lactente.","D":"Revacinar o lactente e, se não apresentar cicatriz, repetir a dose aos 12 meses."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-30855","number":"30855","sourceNumber":"30855","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"De acordo com as evidências científicas disponíveis, a vacinação para influenza em\nidosos deve preferencialmente seguir qual calendário?","options":{"A":"Periodicidade da vacina deve ser julgada caso a caso.","B":"Após epidemias de gripe.","C":"Rotineiramente a cada semestre.","D":"Rotineiramente a cada ano.","E":"Rotineiramente a cada dois anos."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-30857","number":"30857","sourceNumber":"30857","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Após vacinação com BCG, em qual idade deve haver revacinação se não houver a\npresença da cicatriz vacinal?","options":{"A":"Aos 3 meses de idade.","B":"Aos 6 meses de idade.","C":"Aos 9 meses de idade.","D":"Aos 12 meses de idade.","E":"Não é necessária a comprovação da cicatriz."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-37628","number":"37628","sourceNumber":"37628","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Segundo o calendário básico de vacinação do Ministério da Saúde, qual o item que\nmostra vacinação atrasada?","options":{"A":"Criança de 4 meses já fez: 2ª dose da tetra,\n2ª dose da rotavírus, 2ª dose da sabin, 2ª\ndose da hepatite B, 1ª dose da BCG, 2ª dose\nda vacina antipneumocócica e 1ª dose da\nmeningocócica C.","B":"Criança de 6 meses já fez: 1ª dose da BCG,\n1ª dose da tríplice viral, 3ª dose da tetra, 3ª\ndose da sabin, 3ª dose da hepatite B, 2ª dose\n\nda rotavírus, 3ª dose da vacina antipneumocócica\ne 2ª dose da meningocócica C.","C":"Criança de 15 meses já fez: 1ª dose da BCG,\n1ª dose da tríplice viral, 3ª dose da tetra, 3ª\ndose da sabin, 3ª dose da hepatite B, 2ª dose\n\nda rotavírus, 3ª dose da vacina antipneumocócica\ne 2ª dose da meningocócica\n\nC. Reforços da Sabin, DTP,\nantipneumocócica e meningocócica C.","D":"Criança de 12 meses já fez: 1ª dose da BCG,\n1ª dose da tríplice viral, 3ª dose da tetra, 3ª\ndose da sabin, 3ª dose da hepatite B, 2ª dose\n\nda rotavírus, 3ª dose da vacina antipneumocócica\ne 2ª dose da meningocócica C\n\ne da antipneumocócica."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-32527","number":"32527","sourceNumber":"32527","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"O obstetra lhe comunica que a mãe de um recém-nascido (RN), o qual ele fez o parto,\napresenta positividade para o antígeno de superfície de hepatite B (AgHBs). A conduta mais\napropriada para o RN neste caso é:","options":{"A":"Administrar vacina contra hepatite B.","B":"Administrar imunoglobulina específica contra hepatite B.","C":"Aguardar sorologia da mãe para o antígeno e do vírus da hepatite (AgHBe) para definir a\nconduta.","D":"Administrar imunoglobulina específica contra hepatite B e vacina contra hepatite B.","E":"Aguardar a sorologia do RN para AgHBs para definir a conduta."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-36956","number":"36956","sourceNumber":"36956","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"A nova vacina contra Pneumococo introduzida em 2010 no Programa Nacional de\nVacinação tem as seguintes características:","options":{"A":"7 sorotipos de Pneumococo conjugados com\na proteína CRM157.","B":"10 sorotipos de Pneumococo conjugados\ncom a proteína D do H. influenzae não\nsorotipável.","C":"13 sorotipos de Pneumococo conjugados\ncom a proteína CRM157.","D":"23 sorotipos de Pneumococo conjugados\ncom a proteína D do H. influenzae não\nsorotipável."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-29444","number":"29444","sourceNumber":"29444","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Sobre ferimentos causados por mordeduras, marque o item CORRETO:","options":{"A":"Os ferimentos por mordeduras de animais devem ser extensamente irrigados, desbridados e não\npodem ser suturados.","B":"Os ferimentos por mordeduras humanas devem ser extensamente irrigados, desbridados e\npodem ser suturados, dependendo das outras condições locais.","C":"As mordidas por cães são mais comuns, contando com 80 a 90 % dos casos. O antibiótico\nsistêmico de primeira escolha é amoxilina/clavulanato.","D":"As mordidas por felinos são o segundo tipo mais comum, contando com 5 a 15% dos casos. O\nantibiótico sistêmico de primeira escolha é a cefalexina."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-24329","number":"24329","sourceNumber":"24329","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Paulinho, 15 meses, portador da Síndrome da Imunodeficiência Adquirida, apresentou,\nhá uma semana, pneumonia por Pneumocystis e\ncandidíase de esôfago. Na ocasião, sua\ncontagem de LT-CD4 era de 200 células por mm3 (milímetros cúbicos). Se Paulinho fosse realizar\nas próximas vacinas em um curto período de tempo, provavelmente sua pediatra indicaria:","options":{"A":"todas as vacinas, sem restrições.","B":"vacina inativada (Salk) contra poliomielite.","C":"vacina contra hepatite C.","D":"vacina tríplice viral."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-25471","number":"25471","sourceNumber":"25471","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Paciente procura atendimento médico por ter sido mordido na mão pelo cão de\nestimação. Qual a conduta em relação à prevenção da raiva?","options":{"A":"Apenas observar o cão","B":"Apenas duas doses de vacina e observar o cão","C":"Apenas três doses de vacina e observar o cão","D":"Três doses de vacina, soro antirrábico e observar o cão","E":"Cinco doses de vacina e soro antirrábico"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-9128","number":"9128","sourceNumber":"9128","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Lucas, 7 meses, não está mais sendo amamentado, pois sua mãe Nicole mudou-se\npara São Paulo, deixando o bebê sob os\ncuidados da avó. Lucas nasceu de parto normal, com 35\nsemanas de gestação, pesando 2.300 gramas. Vivem em casa própria (de material aproveitado) no\nPirambu (bairro da periferia de Fortaleza), a avó, 2 filhas solteiras, Lucas e mais 3 crianças de\n2, 3\ne 5 anos. A renda mensal da família são R$ 150,00 reais que uma das filhas recebe como\n\n?flanelinha?. O médico de família solicitou o Cartão de Vacinas de Lucas. Quais as vacinas que\nLucas já deveria ter recebido, segundo\norientações do Ministério da Saúde?","options":{"A":"BCG; Hepatite B (1° dose), Pólio (2 doses), Tetravalente (2 doses).","B":"BCG; Hepatite B (2 doses), Pólio (2 doses) Tríplice viral, Tetravalente (2 doses).","C":"BCG; Hepatite B (3 doses), Pólio (3 doses), Tetravalente (3 doses).","D":"BCG; Hepatite B (3 doses), Pólio (3 doses), Tríplice viral (3 doses)."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-7294","number":"7294","sourceNumber":"7294","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"A bronquiolite é uma doença respiratória aguda de crianças, que incide principalmente\ndurante o inverno e primavera. Na definição do\ntratamento, é importante afirmar que:","options":{"A":"a teofilina é a droga de primeira opção terapêutica.","B":"as medidas de suporte resolvem a maioria dos casos.","C":"o corticoide está indicado nos casos de quadros recorrentes.","D":"os antibióticos de amplo espectro estão indicados em lactentes jovens.","E":"o uso de broncodilatadores venosos diminui o tempo de evolução da doença."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-6956","number":"6956","sourceNumber":"6956","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Menino, 4 anos, chega ao Pronto-Socorro com dispneia, febre e tosse há 2 dias. Após o\nachado radiológico, qual a conduta mais\napropriada (VER IMAGEM)?","options":{"A":"Colher hemograma, iniciar ceftriaxona e solicitar tomografia de tórax para complementar o\ndiagnóstico.","B":"Puncionar a pleura e drenagem pleural a depender se empiema ou não. Iniciar penicilina\ncristalina.","C":"Drenagem pleural e iniciar a vancomicina pela alta resistência aos betalactâmicos.","D":"Colher hemograma. Iniciar oxacilina e gentamicina. Essa última somente por 5 dias e para\npotencializar o efeito da primeira.","E":"Colher hemocultura. Iniciar clindamicina e cetriaxona para uma cobertura mais ampla, tendo em\nvista a idade da criança."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":["question_bank/media/medcurso/med-pediatria-med-ped-03/6956.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-9097","number":"9097","sourceNumber":"9097","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em relação à profilaxia do tétano em ferimentos cutâneos, marque a alternativa\nCORRETA:","options":{"A":"Em pacientes com ferimentos extensos, contaminados ou com presença de corpos estranhos e\ncom situação vacinal desconhecida, recomenda-se: tratamento do ferimento, vacinação com\ntoxoide tetânico e gamaglobulina antitetânica ou soro antitetânico.","B":"Em pacientes sem história vacinal de toxoide tetânico e apresentando ferimentos pequenos e\nlimpos, indica-se: tratamento do ferimento, vacinação com toxoide tetânico e gamaglobulina\nantitetânica ou soro antitetânico.","C":"Em pacientes adultos com ferimentos pequenos e limpos e história vacinal de 3 doses de\ntoxoide tetânico há 9 anos, recomenda-se: tratamento do ferimento e vacinação com toxoide\ntetânico.","D":"Em pacientes com ferimentos extensos, contaminados ou com presença de corpos estranhos e\nhistória vacinal de 3 doses de toxoide tetânico há 6 anos, recomenda-se: tratamento do ferimento,\nvacinação com toxoide tetânico e gamaglobulina antitetânica ou soro antitetânico."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8890","number":"8890","sourceNumber":"8890","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um casal que acabou de ganhar um bebê é atendido no ambulatório, e pergunta sobre\nqual medida mais eficaz para reduzir a chance da ocorrência da síndrome da morte súbita da\ninfância. A orientação mais adequada é posicionar o bebê em qual posição de dormir?","options":{"A":"posição supina (decúbito dorsal).","B":"posição prona (decúbito ventral).","C":"posição semissentada.","D":"posição lateral (decúbito lateral direito).","E":"cabeceira elevada, em qualquer posição."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8897","number":"8897","sourceNumber":"8897","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Uma menina de 10 meses de idade apresenta pobre ganho ponderal, tosse persistente\ne uma história de pneumonias de repetição\n(três eventos nos últimos quatro meses). Sua mãe\nrelata que as fezes da menina são muito grandes e com odor muito fétido. Considerando a melhor\nhipótese diagnóstica, o procedimento propedêutico mais apropriado é:","options":{"A":"Tomografia computadorizada do tórax","B":"Dosagem de imunoglobulinas séricas","C":"Teste de intradermoreação com PPD","D":"Raios-X de tórax em inspiração e expiração","E":"Dosagem de sódio e cloro no suor"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8901","number":"8901","sourceNumber":"8901","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Uma menina de dois anos e meio é trazida à unidade de emergência na madrugada\ncom súbito desenvolvimento de dispneia ruidosa à\ninspiração, marcantes retrações torácicas,\nbatimento de asas de nariz e uma tosse rouca. Ela apresenta um quadro de resfriado leve há dois\ndias. O diagnóstico mais provável é:","options":{"A":"Crise aguda de asma","B":"Epiglotite","C":"Bronquiolite","D":"Crupe viral","E":"Corpo estranho no brônquio principal direito"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8904","number":"8904","sourceNumber":"8904","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um menino de quatro anos é trazido para avaliação. O menino apresenta quadros\nrecorrentes de tosse e sibilância, associados\na processos virais, com ou sem febre. Ultimamente,\nos sintomas têm ocorrido mais de três vezes por semana (tosse seca, associada à atividade física e\nmudanças de ambiente), mas a criança não interrompe suas atividades. A tosse compromete a\nnoite da criança cerca de uma vez por semana. Não há tratamento prévio para asma. Considerando\neste diagnóstico, a classificação mais adequada de asma para esta criança é:","options":{"A":"Leve intermitente","B":"Leve persistente","C":"Moderada persistente","D":"Severa intermitente","E":"Severa persistente"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8906","number":"8906","sourceNumber":"8906","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Uma menina de 14 anos apresenta-se com febre baixa e tosse há 3 semanas. Seu\nexame radiológico de tórax evidencia uma\npneumonia intersticial. O diagnóstico mais provável é:","options":{"A":"Pneumonia viral","B":"Pneumonia por Mycobacterium tuberculosis","C":"Pneumonia por Mycoplasma","D":"Pneumonia aspirativa","E":"Pneumonia por Chlamydia"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-255717","number":"255717","sourceNumber":"255717","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um paciente de 4 dias de vida apresenta considerável cianose neonatal, hipoxemia\nimportante. Durante a gestação, o pré-natal foi\ninadequado. Entretanto, o recém-nascido nasceu a\ntermo. Foi realizado um ecocardiograma transtorácico de emergência, que demonstrou\ntransposição de grandes vasos. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Em geral, as vacinações para recém-nascidos, pelo calendário do\nMinistério da Saúde, são dispensáveis até o primeiro mês de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-214362","number":"214362","sourceNumber":"214362","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Paciente R. A. L., 26 anos de idade, com histórico de vacinação antitetânica completa\nna infância, mas omissão do reforço aos 15\nanos e 25 anos de idade, cortou propositalmente\nambos os pulsos com tesoura, gerando ferimento cortocontuso com exposição da derme, mas sem\nexposição dos planos musculares. Refere que realizou o ato como tentativa de autoextermínio por\nouvir, há vários meses, vozes de comando que o orientavam a se ferir e a ferir outras pessoas. No\natendimento, mostra importante agitação, estado hipervigil e hipotenacidade. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A imunoglobulina\nantitetânica está indicada para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-152127","number":"152127","sourceNumber":"152127","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Lactente de um mês de idade é levado à unidade básica de saúde para sua segunda\nconsulta de puericultura. A mãe relata que\no paciente está em aleitamento materno exclusivo,\npeso= 4.125 g ( peso de nascimento = 3.620 g), comprimento de 53 cm, e perímetro cefálico de 36\ncm. Com base nessa situação, e considerando os conhecimentos médicos a ele relacionados,\njulgue o item a seguir. Se, ao completar dois meses de vida, esse paciente estivesse apresentando\num quadro diarreico agudo febril, estaria justificado um possívell adiamento vacinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-131811","number":"131811","sourceNumber":"131811","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Considere hipoteticamente que uma criança de nove meses de idade, natural de\nBarreiras-BA e residente no Distrito Federal há dois meses, é levada à Unidade Básica de Saúde\npara consulta pediátrica de rotina. O pediatra observa o cartão da criança no qual consta a\naplicação da dose da vacina BCG, primeira dose da vacina de hepatite B e da vacina rotavírus\nhumano. Conforme o calendário vacinal do Ministério da Saúde, quanto à atualização vacinal da\ncriança, assinale a alternativa correta.","options":{"A":"Hepatite B, pneumocócica 10-valente, tríplice viral, VOP e meningocócica C.","B":"Hepatite B, pneumocócica 10-valente, pentavalente, VOP e meningicócica C e rotavírus\nhumano.","C":"Hepatite B, pneumocócica 10-valente, pentavalente, tríplice viral, VOP, meningocócica C,\nrotavírus humano e hepatite A.","D":"Hepatite B, pneumocócica 10-valente, pentavalente, VOP e meningocócica C.","E":"Hepatite B, tríplice viral, VOP e meningocócica C."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-135060","number":"135060","sourceNumber":"135060","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Acerca da bronquiolite viral aguda (BVA), julgue o item que se segue. A Sociedade\nBrasileira de Pediatria recomenda o uso de palivizumabe na profilaxia da BVA para todos os\nrecém-nascidos, independentemente da idade gestacional ou do peso ao nascer.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-134977","number":"134977","sourceNumber":"134977","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Com relação à infecção do trato urinário na faixa etária pediátrica, julgue o próximo\nitem. Em paciente pediátrico que ainda não tem controle miccional, a coleta de urina com saco\ncoletor é o método indicado no caso de a cultura ter sido positiva, o que deve determinar o\ntratamento antimicrobiano adequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-108227","number":"108227","sourceNumber":"108227","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Julgue o item que se segue, relativo a doença infecciosa na infância e na adolescência.\nA vacina contra papilomavírus humano (HPV) é\nconstituída por recombinante genético de quatro\ntipos de vírus HPV, possui eficácia imunogênica em 98,8% para jovens com idade entre nove e\ntreze anos de idade e deve ser administrada em três doses, devendo ser administrada a segunda\ndose seis meses após a primeira; e a terceira após sessenta meses da primeira administração.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-82081","number":"82081","sourceNumber":"82081","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"No que concerne à atenção à saúde da criança, julgue o próximo item. Em casos de\nfilhos de mães portadoras de hepatite B, a amamentação traz risco adicional ao recém-nascido,\nmesmo que ele tenha recebido a primeira dose da vacina e a imunoglobulina humana anti-hepatite\nB.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-49177","number":"49177","sourceNumber":"49177","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um lactente com dois meses de vida foi levado à consulta de puericultura sem queixas.\nEle foi um recém-nascido de termo, adequado\npara a idade gestacional e apresentou Apgar de\nprimeiro e quinto minutos igual a 9. Está em aleitamento materno exclusivo e com calendário\nvacinal em dia. No exame físico, apresenta obesidade, com índice de massa corporal acima do\npercentil 95 para idade e sexo e sem outras alterações. Com referência ao caso clínico acima\napresentado e a aspectos relacionados a lactentes com a idade ali mencionada, julgue o próximo\nitem. O calendário vacinal da Sociedade Brasileira de Pediatria de 2011 indica que a criança em\nquestão deve receber, na idade em que se encontra, as seguintes vacinas: tríplice bacteriana\nacelular, anti-hemófilos, antipoliomielite oral, antipneumocócica conjugada e antirrotavírus.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-32147","number":"32147","sourceNumber":"32147","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um adolescente foi visitar um amigo e, ao brincar com o animal de estimação da\nfamília, foi mordido na face por um mico\n(macaco Sagui). O dono do animal informou que cria o\nanimal há três anos (domiciliado) e que ele nunca causou problema para as pessoas. Com base no\nprotocolo de profilaxia da raiva humana, com vacina de cultivo celular do Ministério da Saúde, a\nconduta correta nesse caso é:","options":{"A":"Não fazer nada, já que o animal é sadio e domiciliado.","B":"Observar o animal durante dez dias após a exposição.","C":"Iniciar esquema profilático com duas doses: uma no dia 0 e outra no dia 3.","D":"Iniciar imediatamente o esquema profilático com cinco doses de vacina, administradas nos dias\n0, 3, 7,14 e 28.","E":"Iniciar imediatamente o esquema profilático com soro e cinco doses de vacina, administradas\nnos dias 0, 3, 7,14 e 28."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-37967","number":"37967","sourceNumber":"37967","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Com relação a patologias pediátricas, julgue o item. Para uma criança com doze dias\nde vida, que teve diagnóstico confirmado de infecção do trato urinário por Escherichia coli, o\ntratamento de escolha é o uso da penicilina ou da ampicilina por via oral durante dez dias.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-37974","number":"37974","sourceNumber":"37974","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em setembro de 2010, o Brasil foi o primeiro país das Américas a entregar seu relatório\npara a certificação de eliminação do\nsarampo à Organização Pan-Americana de Saúde (OPAS). O\núltimo caso autóctone de sarampo, relacionado à transmissão sustentada no território brasileiro, foi\nregistrado no ano 2000, no estado do Mato Grosso do Sul. A respeito do controle dessa\nenfermidade, julgue o item. A cobertura vacinal contra o sarampo corresponde ao percentual de\ncrianças de um ano que receberam pelo menos uma dose da vacina tríplice viral, em determinado\nespaço geográfico, no ano considerado.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-37975","number":"37975","sourceNumber":"37975","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em setembro de 2010, o Brasil foi o primeiro país das Américas a entregar seu relatório\npara a certificação de eliminação do\nsarampo à Organização Pan-Americana de Saúde (OPAS). O\núltimo caso autóctone de sarampo, relacionado à transmissão sustentada no território brasileiro, foi\nregistrado no ano 2000, no estado do Mato Grosso do Sul. A respeito do controle dessa\nenfermidade, julgue o item. As ações de vigilância epidemiológica locais, articuladas com as do\nMinistério da Saúde, são fundamentais para o controle do sarampo, frente à ocorrência de casos\nimportados e relacionados a essa doença no território brasileiro.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-37976","number":"37976","sourceNumber":"37976","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Em setembro de 2010, o Brasil foi o primeiro país das Américas a entregar seu relatório\npara a certificação de eliminação do\nsarampo à Organização Pan-Americana de Saúde (OPAS). O\núltimo caso autóctone de sarampo, relacionado à transmissão sustentada no território brasileiro, foi\nregistrado no ano 2000, no estado do Mato Grosso do Sul. A respeito do controle dessa\nenfermidade, julgue o item. As coberturas elevadas atingidas na campanha de vacinação contra a\nrubéola, realizada em 2008, contribuíram para a eliminação do sarampo no Brasil.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-27533","number":"27533","sourceNumber":"27533","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Recém-nascido higido, com 5 dias de vida, cujo irmão adolescente apresenta quadro\nclínico-radiológico compatível com tuberculose e baciloscopia 3+/4+, ainda sem tratamento\nadequado. A criança ainda não recebeu nenhuma vacinação. Com relação ao recém-nascido, qual\ndeve ser a conduta?","options":{"A":"Internar, radiografar e iniciar esquema tríplice.","B":"Radiografar e iniciar esquema tríplice mesmo antes de ver o resultado da radiografia.","C":"Iniciar quimioprofilaxia primária e após, aplicar o teste tuberculínico e se negativo vacinar com\nBCG.","D":"Iniciar quimioprofilaxia primária e concominantemente vacinar com BCG.","E":"Iniciar quimioprofilaxia secundária e vacinar imediatamente com BCG."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-29730","number":"29730","sourceNumber":"29730","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"A respeito de situações clinicoepidemiológicas em pediatria, julgue o item seguinte.De\nacordo com as normas do Programa Nacional de\nImunizações do Ministério da Saúde, um\nadolescente residente no DF, que não tem como comprovar vacinação anterior, por ocasião da sua\nprimeira visita a uma unidade de saúde, deve receber apenas as seguintes vacinas: lª dose contra\nhepatite B, tríplice viral e dupla (dT) adulto.","options":{"A":"Certo","B":"Errado"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-7569","number":"7569","sourceNumber":"7569","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Lactente masculino de um ano e dois meses de idade foi atendido no pronto-socorro\ncom história de quadro gripal há uma semana.\nSegundo a mãe, desde a madrugada, a criança está\nchorando muito e levando as mãos até as orelhas com bastante frequência. À otoscopia: OD\n(membrana timpânica abaulada e hiperemia) e OE (otorreia). Assinale a alternativa quanto à\nconduta que deve ser adotada, segundo o Consenso da Sociedade Brasileira de Pediatria.","options":{"A":"Atitude expectante e revisão da criança após 48 horas.","B":"Prescrever amoxicilina e revisão da criança após 72 horas.","C":"Prescrever antibiótico tópico otológico e descongestionantes sistêmicos.","D":"Prescrever cefalexina, solução fisiológica nasal e descongestionantes sistêmicos.","E":"Prescrever levofloxacina e rever a criança após 48 horas."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-13863","number":"13863","sourceNumber":"13863","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um lactente com 6 meses de vida foi com a mãe ao ambulatório de crescimento e\ndesenvolvimento. Revendo a história, o pediatra observou que o bebê nasceu de parto vaginal\napós uma gestação de baixo risco. Chorou forte ao nascer e permaneceu o tempo todo com a mãe\nno alojamento conjunto. Recebeu alta com 48 horas de vida, sendo amamentado exclusivamente\nao seio materno e sem intercorrência clínica. O cartão de vacinação está atrasado e ele tomou\napenas a primeira dose da vacina contra a hepatite B, ainda no hospital. A mãe referiu que a\ncriança era amamentada exclusivamente ao seio até o momento da consulta. Com base nessa\nsituação, julgue os seguintes itens. I- O fato de a criança ter permanecido em alojamento conjunto\ncontínuo por 48 horas contribuiu para a manutenção do aleitamento materno exclusivo até os 6\nmeses de vida. II- Considerando que a criança tenha pesado 3.000 g ao nascer, seria correto\nesperar que, no momento da consulta, ele pesasse aproximadamente 7.000 g. III- Segundo o\nPrograma Nacional de Imunização do Ministério da Saúde do Brasil, a criança em questão deveria\nser imunizada com as seguintes vacinas: BCG intradérmico, segunda dose da vacina contra\nhepatite B, primeira dose da vacina tetra, antipoliomielite e contra rotavírus. IV- O pediatra deve\nrecomendar a introdução de alimentos sólidos complementares, começando com uma fruta pela\nmanhã ou tarde e papas de legumes no horário do futuro almoço.\n\nV- A próxima visita de controle deve ser feita aos 9 meses de vida da criança. A quantidade de\nitens certos é igual a:","options":{"A":"1.","B":"2.","C":"3.","D":"4.","E":"5."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-227422","number":"227422","sourceNumber":"227422","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"A respeito da vacinação contra o HPV, julgue o item seguinte. A vacina contra o HPV,\nalém de ser eficaz na prevenção da infecção por esse vírus na região genital de mulheres com vida\nsexual ativa, também é indicada para meninas adolescentes impúberes, as quais devem receber 3\ndoses da vacina, no esquema 0, 1 a 2 e 6 meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-227449","number":"227449","sourceNumber":"227449","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue o\nitem que se segue. Grávidas devem vacinar-se\ncontra o sarampo apenas em caso de surto vigente no país, pois, nessas circunstâncias, os\nbenefícios superam os riscos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-183890","number":"183890","sourceNumber":"183890","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"No que se refere à imunização, julgue o item seguinte. A imunização passiva\nartificialmente adquirida garante proteção mais\nduradoura e menores reações de sensibilidade se\ncomparada à imunização ativa artificialmente adquirida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-159589","number":"159589","sourceNumber":"159589","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Um lactente de dois meses de idade foi levado ao médico por sua mãe para uma\nconsulta de rotina. A mãe referiu que nunca\nhavia amamentado no peito e que atualmente o\nlactente era alimentado com leite de vaca in natura integral e açúcar, em doses de 150 mL cinco\nvezes ao dia, e água nos intervalos. O médico observou ainda, no cartão da criança, que o lactente\nhavia recebido a primeira dose da vacina contra hepatite B e o BCG intradérmico. No que se refere\na esse caso clínico, julgue o item subsecutivo. Essa criança deverá receber as seguintes vacinas:\ntetravalente (difteria, tétano, pertussis, hemófilo B), anti-hepatite B, antipoliomielite inativada\n(Salk\nou VIP), antipneumocócica decavalente, antirrotavírus humano.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-159609","number":"159609","sourceNumber":"159609","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Com relação à adequada prática clínica nos cuidados pré-natais, julgue o seguinte item.\nO reforço da vacina contra febre amarela,\nquando necessário, pode ser feito em gestantes, uma\nvez que essa vacina é composta por vírus inativado e não oferece risco à saúde da mãe ou do feto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-22201","number":"22201","sourceNumber":"22201","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Com relação às doenças infectocontagiosas, julgue o item a seguir. Considere que um\nbebê de 6 meses de idades tenha sido\nvacinado no dia 17 de setembro com a vacina oral contra a\npoliomielite (VOP), seguindo o calendário nacional de vacinação. No dia 19 de setembro, ocorreu a\ncampanha nacional de imunização contra a poliomielite, utilizando-se a VOP. Nessa situação, esse\nbebê não deveria receber a vacina da campanha, porque já foi vacinado 2 dias antes.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8688","number":"8688","sourceNumber":"8688","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"No próximo item, é apresentada uma situação clínica hipotética envolvendo a interface\nda pediatria com a cirurgia pediátrica, seguida\nde uma assertiva a ser julgada. Uma escolar com\nhistória de febre e tosse seca intensa apresentou, subitamente, dificuldade para respirar. Ao\nexame, a criança estava angustiada, com taquipneia e dispneia intensa, cianose de extremidades e\nhipotensão arterial. Uma radiografia do tórax mostrou imagem de hipertransparência de hemitórax\nesquerdo, ausência de vasos e desvio do coração para a direita. Nessa situação, o diagnóstico é\nde pneumotórax hipertensivo à esquerda e está indicada toracocentese de urgência como medida\ninicial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8693","number":"8693","sourceNumber":"8693","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Desde a década passada, a Atenção Integral às Doenças Prevalentes da Infância\n(AIDPI) revelou-se uma estratégia adequada à\ndisposição dos médicos, com um conjunto básico de\nintervenções baseadas em evidências científicas que permitem prevenir e tratar eficazmente as\nprincipais doenças e problemas que afetam a saúde nos primeiros anos de vida. Acerca dessas\nevidências, julgue o item. O caso de uma criança de dois anos de idade que tosse há três dias,\nconsegue ingerir líquidos e que, ao exame físico, apresenta frequência respiratória de 50 incursões\npor minuto, sem retrações, estridor ou sibilância não deve ser classificado como pneumonia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8695","number":"8695","sourceNumber":"8695","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Desde a década passada, a Atenção Integral às Doenças Prevalentes da Infância\n(AIDPI) revelou-se uma estratégia adequada à\ndisposição dos médicos, com um conjunto básico de\nintervenções baseadas em evidências científicas que permitem prevenir e tratar eficazmente as\nprincipais doenças e problemas que afetam a saúde nos primeiros anos de vida. Acerca dessas\nevidências, julgue o item. O caso de uma criança que se queixa de dor no ouvido e que, na\nobservação, apresenta secreção purulenta no ouvido e tumefação dolorosa ao toque atrás da\norelha deve ser classificado como mastoidite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8696","number":"8696","sourceNumber":"8696","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"No item subsequente, é apresentada uma situação hipotética acerca das situações\nclínicas encontradas em ambulatório e emergência\npediátricos, seguida de uma assertiva a ser\njulgada. Um escolar apresenta, há dois dias, febre moderada, odinofagia e volumoso aumento dos\ngânglios submandibulares e cervicais, que se apresentam dolorosos e quentes. Ao exame da\norofaringe, foram observadas hipertrofia e secreção purulenta em amígdalas e secreção pultácea\nem orofaringe. Nessa situação, o agente etiológico mais provável é o Streptococcus pyogenes e a\ncriança deve ser tratada com um antibiótico à base de penicilina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-8698","number":"8698","sourceNumber":"8698","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"No item subsequente, é apresentada uma situação hipotética acerca das situações\nclínicas encontradas em ambulatório e emergência\npediátricos, seguida de uma assertiva a ser\njulgada. Um escolar com taquidispneia e sibilos foi diagnosticado como tendo asma aguda grave.\nNessa situação, o tratamento indicado, conforme o III Consenso Brasileiro do Manejo da Asma,\nconsiste de oxigenoterapia, administração de beta 2 agonista por via inalatória a cada 20 minutos\npor 3 vezes em 1 hora. Se o paciente não responder a este último, deve-se ministrar aminofilina por\nvia endovenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-304877","number":"304877","sourceNumber":"304877","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Felipe, 8 meses de idade, natural de Lauro de Freitas (BA), mudou-se para Vitória há 1\nmês e foi encaminhado para consulta de\npuericultura na Unidade Básica de Saúde de Maruípe pela\nagente comunitária. Durante a consulta, ao avaliar o cartão de vacina, observa-se que estão\nconfirmadas as seguintes vacinas: BCG (dose única ao nascimento), hepatite B (dose ao\nnascimento), pentavalente (1ª e 2ª doses), rotavírus (1ª e 2ª doses), pneumocócica 10 valente (1ª e\n2ª doses), meningocócica C (1ª dose), VIP: Poliomielite injetável (1ª e 2ª doses). Quais vacinas\nestão indicadas para Felipe no momento desta consulta, segundo o Programa Nacional de\nImunizações atual?","options":{"A":"Pneumocócica 10-valente, VIP, Meningocócica C, Influenza.","B":"Meningocócica C e Influenza.","C":"Pentavalente, VIP e Pneumocócica 10-valente.","D":"Pentavalente, VIP, Meningócica C, influenza."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-232113","number":"232113","sourceNumber":"232113","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Como se dá a disseminação do vírus rábico no organismo a partir do ponto de\ninoculação?","options":{"A":"O vírus penetra no organismo quando atinge as extremidades e, devido à característica da\nvascularização, facilita sua disseminação hematogênica em direção ao sistema nervoso central.","B":"Após a penetração na pele, o vírus se dissemina por via hematogênica, desenvolve-se em até 4\ndias e, após atingir as meninges, desenvolve o quadro clássico da encefalite rábica.","C":"A doença evolui de forma lenta, considerando a capacidade de replicação viral a partir do ponto\nde inoculação, por via linfática e hematogênica,\nassim, podendo o indivíduo eliminar de forma\ncontínua o vírus através das glândulas salivares.","D":"O vírus rábico se dissemina, preferentemente por via nervosa e, nos casos de pacientes\nimunocomprometidos as vias hematogênica e linfática podem auxiliar na disseminação viral.","E":"O vírus penetra no organismo, multiplica-se no ponto de inoculação, atinge o sistema nervoso\nperiférico e, posteriormente, o sistema nervoso central, quando se dissemina para vários órgãos."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-106443","number":"106443","sourceNumber":"106443","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Francisco nasceu a termo e saudável, na Maternidade do Hospital Estadual Jayme dos\nSantos Neves. Recebeu a vacina BCG no primeiro dia de vida. Seis meses depois, em uma\nconsulta de rotina, o pediatra notou que Francisco não tinha cicatriz vacinal em seu braço direito.\nQual conduta a ser tomada?","options":{"A":"Fazer PPD e revacinar BCG se PPD menor que 10 mm de diâmetro.","B":"Fazer PPD e revacinar BCG se PPD maior que 10 mm de diâmetro.","C":"Revacinar com BCG.","D":"Aguardar mais 6 meses e reavaliar a cicatriz vacinal.","E":"Não revacinar, considerar a criança já imunizada."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-44016","number":"44016","sourceNumber":"44016","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Luis Felipe nasceu de parto normal, a termo, mãe primípara, sem alterações na\ngestação, exceto baixo ganho ponderal (7 Kg em\n38 semanas) com peso de 2300 g, 48 cm e\nperímetro cefálico de 34 cm. Chegou ao ambulatório do HUCAM aos 12 meses com 10 Kg (peso\npara idade ? escore 0 a +2) e 78 cm (comprimento para idade ? escore 0 a +2), ativo, emitindo\npalavras (mamâ, papá), ficando de pé com apoio, sem andar. Bom apetite, sono tranquilo\n(raramente acorda à noite). Sua alimentação é composta de leite materno (3 a 4x/dia), frutas\n(2x/dia) e come comida de casa (de tudo com pouco sal, mas variada e balanceada) no almoço e\njantar. A mãe do paciente solicita orientação quanto a retirada de fraldas. Marque a alternativa\ncorreta quanto a orientação sobre a retirada das fraldas e uso do sanitário:","options":{"A":"Este treinamento deveria iniciar desde o 9º mês de vida, quando a criança já senta.","B":"Você vibra pela preocupação da mãe e orienta a retirada pela manhã para posterior retirada à\nnoite.","C":"Suas orientações devem ser para seguir a retirada das fraldas quando a criança avisa que\nevacuou, fenômeno que ocorre fisiologicamente com 03 anos ou mais, devido à imaturidade do\nsistema digestório e de seus esfincteres até esta faixa etária.","D":"Você não recomenda e comenta os traumas que podem acontecer se iniciar este treinamento\nantes dos 03 anos.","E":"Você tranquiliza a mãe, comenta que é cedo para este treinamento que deve se iniciar por volta\ndos 18 meses, compatível com o desenvolvimento neurológico adequado."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-43320","number":"43320","sourceNumber":"43320","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Lactente do sexo feminino com história de febre há três dias, irritabilidade, inapetência\ne vômitos. Nega tosse, coriza, constipação\nintestinaI ou diarreia. Ao exame encontra-se ativo e\nreativo; fontanela anterior normotensa; ausência de lesões de pele; eupneico; acianótico;\nanictérico;\nnormo-hidratado; ACV e AR sem anormalidades; Abdome com peristalse presente, flácido, indolor\ne sem massas ou visceromegalias. Seria correto afirmar, exceto:","options":{"A":"Considerar o diagnóstico de Infecção do Trato Urinário se a coleta da urina for por aspiração\nsuprapúbica e houver crescimento\nbacteriano em qualquer número de um patógeno urinário único,\nexceto 2 a 3000 UFC/mL de estafilocoagulase-negativo.","B":"Considerar o diagnóstico de Infecção do Trato Urinário se a coleta da urina for por cauterização\nuretral e houver crescimento bacteriano entre\n1000 e 50000 UFC/mL de um patógeno urinário\núnico.","C":"Considerar o diagnóstico de Infecção do Trato Urinário se a coleta da urina for com aplicação do\ncoletor adesivo, fechado e estéril após a desinfecção da pele da genitália e com trocas a cada 30\nminutos até que a amostra seja obtida e havendo crescimento bacteriano de um patógeno urinário\núnico maior de 100000 UFC/mL.","D":"Considerar o diagnóstico de Infecção do Trato Urinário se a coleta da urina for por jato médio e\nhouver crescimento bacteriano acima de 5000 UFC/mL de um patógeno urinário único, sendo que a\ncriança está sintomática."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-03-27348","number":"27348","sourceNumber":"27348","collectionBlock":"med:med-pediatria-med-ped-03","collectionLabel":"MED · MED PED 03","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 03","subtopic":"","stem":"Uma lactente de 3 meses de idade apresenta febre há 48 horas e está sem ganhar\npeso adequado desde a sua última consulta médica\nhá 20 dias. Após investigação de outros dados\nde anamnese e exame físico foi observado comprometimento do estado geral e a presença de\nfimose. Foi então pensado em se tratar de infecção urinária, entre outras possibilidades. Dentre as\ncondutas abaixo, qual a mais adequada em se tratando de infecção urinária a fim de confirmar o\ndiagnóstico?","options":{"A":"Colher urina para análise de elementos anormais e sedimento e fazer a cultura em seguida,\nsomente se houver alteração neste exame.","B":"Colher urina para cultura por jato médio e considerar o diagnóstico se houver qualquer\ncrescimento bacteriano.","C":"Colher urina para cultura por punção suprapúbica.","D":"Colher urina com saco coletor após higienização correta e considerar o diagnóstico se houver\ncrescimento bacteriano.","E":"Colher urina por sondagem vesical."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 03/MED PED 03.txt","sourceLabel":"MED · MED PED 03","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 03","MED"],"answerSource":"missing","commentDeferred":true}]};
